// @ts-check
/** @typedef {{ row: number, dir: number, base: number, w: number, pos: number }} Lane */
/** @typedef {{ flow: Arcade.Lib.Flow, sc: Arcade.Lib.Score, frog: { x: number, row: number, hop: number, down: boolean }, lanes: Lane[], dying: number, splash: { x: number, y: number } | null, lastDeath: string, crossings: number, pops: Arcade.Lib.Pop[], art: Record<string, Arcade.Sprite> }} State */

// Log Hopper: a frog hops over a river on floating logs. Numbers live in CFG.
const CFG = {
  lives: 3,
  tile: 16,
  rows: 12,
  startRow: 11,
  midRow: 6,
  goalRow: 1,
  dyingFrames: 30,
  crossScore: 100,
  speedStep: 0.1,
  speedMax: 0.5,
  ring: 320, // 4 logs, 80 apart
  spacing: 80,
  logs: 4,
  hopFrames: 8,
};
// river lanes, from the start bank up: row, direction (+1 right), start speed, log length
const LANES = [
  [10, 1, 0.5, 64], [9, -1, 0.7, 48], [8, 1, 0.6, 48], [7, -1, 0.8, 56],
  [5, 1, 0.6, 48], [4, -1, 0.9, 40], [3, 1, 0.7, 48], [2, -1, 1.0, 40],
];
const FROG = [
  "..gg....gg..",
  ".g55g..g55g.",
  ".g05gggg50g.",
  "..gihhhhig..",
  "..ghhhhhhg..",
  ".gghhhhhhgg.",
  "gihhhhhhhhig",
  "gghhhhhhhhgg",
  ".gghhhhhhgg.",
  "..ghhhhhhg..",
  ".ggg.gg.ggg.",
  ".gg......gg.",
];
const HOP_LIFT = [1, 2, 3, 4, 4, 3, 2, 1];

/** @param {State} s */
const startX = (s, g) => (g.W - CFG.tile) / 2;
const speedOf = (/** @type {State} */ s, /** @type {Lane} */ l) => l.base + Math.min(CFG.speedMax, CFG.speedStep * s.crossings);
const isRiver = (/** @type {number} */ row) => row >= 2 && row <= 10 && row !== CFG.midRow;
const logX = (/** @type {Lane} */ l, /** @type {number} */ k) => ((((l.pos + k * CFG.spacing) % CFG.ring) + CFG.ring) % CFG.ring) - 64;
/** is there a log of this lane under x? */
const logUnder = (/** @type {Lane} */ l, /** @type {number} */ cx) => {
  for (let k = 0; k < CFG.logs; k++) {
    const x = logX(l, k);
    if (cx >= x && cx < x + l.w) return true;
  }
  return false;
};
const laneOf = (/** @type {State} */ s, /** @type {number} */ row) => s.lanes.find((l) => l.row === row);

/** @param {Arcade.G} g @param {State} s */
function respawn(g, s) {
  s.frog = { x: startX(s, g), row: CFG.startRow, hop: 0, down: false };
  s.dying = 0;
  s.splash = null;
}

/** @param {Arcade.G} g @param {State} s */
function newGame(g, s) {
  s.sc = g.lib.score.newScore(g, { lives: CFG.lives });
  s.crossings = 0;
  s.lastDeath = "";
  s.lanes = LANES.map(([row, dir, base, w]) => ({ row, dir, base, w, pos: g.rnd(CFG.spacing) }));
  s.pops = [];
  respawn(g, s);
}

/** the frog is lost: life gone now, back at the start after dyingFrames
 * @param {Arcade.G} g @param {State} s @param {string} why */
function die(g, s, why) {
  const { score, fx } = g.lib;
  score.loseLife(s.sc);
  s.lastDeath = why;
  s.dying = CFG.dyingFrames;
  s.splash = { x: s.frog.x + CFG.tile / 2, y: s.frog.row * CFG.tile + CFG.tile / 2 };
  g.sfx("hit");
  fx.pop(s.pops, why === "edge" ? "WHOOPS" : "SPLASH", s.splash.x, s.splash.y - 10, g.colors.white);
}

/** @type {Arcade.Cart<State>} */
export default {
  init(g) {
    const s = /** @type {State} */ ({ flow: g.lib.flow.newFlow() });
    s.art = { frog: g.sprite(FROG) };
    newGame(g, s);
    return s;
  },

  update(g, s) {
    const { flow, score, fx } = g.lib;
    flow.tick(s.flow);
    fx.tick(s.pops);
    if (s.flow.mode !== "play") {
      if (flow.startPressed(g, s.flow)) {
        if (s.flow.mode === "title") newGame(g, s);
        flow.go(s.flow, s.flow.mode === "title" ? "play" : "title");
      }
      return;
    }
    const f = s.frog;
    const T = CFG.tile;

    // the frog rides the log it sits on
    if (!s.dying && isRiver(f.row)) {
      const l = laneOf(s, f.row);
      if (l) f.x += l.dir * speedOf(s, l);
    }
    // the logs float on
    for (const l of s.lanes) l.pos += l.dir * speedOf(s, l);

    if (s.dying) {
      s.dying -= 1;
      if (s.dying === 0) {
        if (score.isOver(s.sc)) {
          score.commit(g, s.sc);
          g.sfx("lose");
          flow.go(s.flow, "over");
        } else respawn(g, s);
      }
      return;
    }

    // one hop for each press
    if (f.hop > 0) f.hop -= 1;
    let dx = 0;
    let dr = 0;
    if (g.btnp("up")) dr = -1;
    else if (g.btnp("down")) dr = 1;
    else if (g.btnp("left")) dx = -T;
    else if (g.btnp("right")) dx = T;
    const nr = f.row + dr;
    const nx = f.x + dx;
    if ((dx || dr) && nr >= CFG.goalRow && nr <= CFG.startRow && nx >= 0 && nx <= g.W - T) {
      f.row = nr;
      f.x = nx;
      f.hop = CFG.hopFrames;
      if (dr) f.down = dr > 0;
      g.sfx("jump");
    }

    // where did it land?
    if (f.row === CFG.goalRow) {
      score.addPoints(s.sc, CFG.crossScore);
      s.crossings += 1;
      g.sfx("coin");
      fx.pop(s.pops, `+${CFG.crossScore}`, f.x + T / 2, f.row * T, g.colors.yellow);
      respawn(g, s);
      return;
    }
    if (isRiver(f.row)) {
      const l = laneOf(s, f.row);
      const cx = f.x + T / 2;
      if (cx < 0 || cx >= g.W) die(g, s, "edge");
      else if (!l || !logUnder(l, cx)) die(g, s, "water");
    }
  },

  draw(g, s) {
    const { fx } = g.lib;
    const c = g.colors;
    const T = CFG.tile;
    g.cls(c.night);
    if (s.flow.mode === "title") {
      const art = fx.title(g, "LOG HOPPER", s.sc.best, { color: c.lime });
      g.spr(s.art.frog, art.cx - 18, art.cy - 32, { scale: 3 });
      g.text("STICK: HOP, ONE PRESS = ONE HOP", g.W / 2, art.cy + 10, c.white, { align: "center" });
      g.text("RIDE LOGS TO THE FAR BANK", g.W / 2, art.cy + 20, c.white, { align: "center" });
      return;
    }
    // banks and river
    for (let row = 1; row < CFG.rows; row++) {
      const y = row * T;
      if (isRiver(row)) {
        g.rectfill(0, y, g.W, T, c.blue);
        for (let i = 0; i < 9; i++) {
          const rx = (i * 37 + row * 23 + (g.frame >> 3) * (row % 2 ? 1 : -1) * 2 + 512) % g.W;
          g.line(rx, y + 3 + ((i * 5 + row) % 9), rx + 5, y + 3 + ((i * 5 + row) % 9), c.sky);
        }
      } else {
        g.rectfill(0, y, g.W, T, c.forest);
        for (let i = 0; i < 16; i++) g.pset((i * 41 + row * 17) % g.W, y + 2 + ((i * 7) % 12), c.green);
        if (row === CFG.goalRow) {
          for (let i = 0; i < 8; i++) {
            g.circfill(16 + i * 32, y + 8, 5, c.green);
            g.circfill(16 + i * 32 - 1, y + 7, 1, c.yellow);
          }
        }
      }
    }
    // logs
    for (const l of s.lanes) {
      const y = l.row * T + 2;
      for (let k = 0; k < CFG.logs; k++) {
        const x = Math.round(logX(l, k));
        g.rectfill(x, y, l.w, T - 4, c.brown);
        g.rectfill(x, y, l.w, 2, c.orange);
        g.rect(x, y, l.w, T - 4, c.maroon);
        for (let gx = x + 8; gx < x + l.w - 6; gx += 11) g.line(gx, y + 4, gx + 4, y + 4, c.maroon);
        g.circfill(x + 2, y + 6, 4, c.tan);
        g.circ(x + 2, y + 6, 2, c.brown);
        g.circfill(x + l.w - 3, y + 6, 4, c.tan);
        g.circ(x + l.w - 3, y + 6, 2, c.brown);
      }
    }
    // frog (or its splash)
    const f = s.frog;
    if (s.dying && s.splash) {
      const t = CFG.dyingFrames - s.dying;
      const r = 3 + (t >> 1);
      g.circ(s.splash.x, s.splash.y, r, c.white);
      if (t > 4) g.circ(s.splash.x, s.splash.y, r - 4, c.ice);
      if (t < 12) for (let i = 0; i < 6; i++) g.circfill(s.splash.x + (i - 2.5) * 4, s.splash.y - 3 - ((t * (i % 3 + 2)) >> 1) + t * t / 16, 1, c.white);
    } else {
      const lift = f.hop > 0 ? HOP_LIFT[CFG.hopFrames - f.hop] : 0;
      if (lift) g.circfill(f.x + T / 2, f.row * T + 13, 5, c.navy);
      g.spr(s.art.frog, Math.round(f.x) + 2, f.row * T + 2 - lift, { flipY: f.down });
    }
    // top strip
    g.rectfill(0, 0, g.W, T, c.night);
    g.text(`SCORE ${s.sc.score}  BEST ${s.sc.best}`, 2, 4, c.white);
    fx.lives(g, s.sc.lives, g.W - 2, 5, c.lime);
    fx.draw(g, s.pops);
    if (s.flow.mode === "over") fx.banner(g, "GAME OVER", s.sc.newBest ? "NEW BEST!" : `SCORE ${s.sc.score}`);
  },

  probe(g, s) {
    return {
      W: g.W,
      H: g.H,
      tile: CFG.tile,
      mode: s.flow.mode,
      frog: { x: s.frog.x, cx: s.frog.x + CFG.tile / 2, row: s.frog.row },
      startX: startX(s, g),
      lanes: s.lanes.map((l) => ({ row: l.row, dir: l.dir, speed: speedOf(s, l), base: l.base, logs: [0, 1, 2, 3].map((k) => ({ x: logX(l, k), w: l.w })) })),
      score: s.sc.score,
      lives: s.sc.lives,
      best: s.sc.best,
      crossings: s.crossings,
      dying: s.dying,
      lastDeath: s.lastDeath,
    };
  },

  poke(g, s, o) {
    if (o.lives !== undefined) s.sc.lives = o.lives;
    if (o.crossings !== undefined) s.crossings = o.crossings;
  },
};
// @ts-check
const RIVER = [10, 9, 8, 7, 5, 4, 3, 2];
const BANK = (r) => r === 11 || r === 6 || r === 1;
const lane = (p, row) => p.lanes.find((l) => l.row === row);
const landsOn = (p, row, m = 6) => lane(p, row).logs.some((l) => p.frog.cx >= l.x + m && p.frog.cx < l.x + l.w - m);
const overWater = (p, row, m = 6) => lane(p, row).logs.every((l) => p.frog.cx < l.x - m || p.frog.cx >= l.x + l.w + m);

/** wait until a hop up is safe, then hop. Returns the probe after the hop. */
async function hopUp(t) {
  for (let i = 0; i < 900; i++) {
    const p = await t.probe();
    if (p.mode !== "play") throw new Error("the game ended while the bot waited to hop");
    if (!p.dying && (BANK(p.frog.row - 1) || landsOn(p, p.frog.row - 1))) return await t.bot.press("up");
    await t.bot.wait(1);
  }
  throw new Error("the bot never found a log to hop onto");
}

/** wait at the start row until there is only water above, then hop into it. */
async function hopIntoWater(t) {
  for (let i = 0; i < 900; i++) {
    const p = await t.probe();
    if (!p.dying && p.frog.row === 11 && overWater(p, 10)) return await t.bot.press("up");
    await t.bot.wait(1);
  }
  throw new Error("the bot never found open water to hop into");
}

/** hop up until the frog is on `row` */
async function climbTo(t, row) {
  for (let i = 0; i < 400; i++) {
    const p = await t.probe();
    if (p.frog.row === row && !p.dying) return p;
    await hopUp(t);
  }
  throw new Error("the bot couldn't reach row " + row);
}

/** play until one crossing is done; keep the lives topped up */
async function cross(t) {
  await t.poke({ lives: 99 });
  for (let i = 0; i < 400; i++) {
    const p = await t.probe();
    if (p.crossings >= 1) return p;
    if (p.frog.row === 2 && !p.dying) {
      const before = p;
      const after = await t.bot.press("up");
      return { before, after };
    }
    await hopUp(t);
  }
  throw new Error("the bot couldn't cross the river");
}

/** @type {Arcade.Checks} */
export default {
  async R1(t) {
    const a = await t.bot.start();
    await t.poke({ lives: 99 });
    const l1 = await t.bot.press("left", 0);
    t.bot.eq(l1.frog.x, a.frog.x - 16, "x after one left press");
    await t.bot.wait(1); // let go of the stick first, so the next press is a new press
    t.bot.eq((await t.bot.hold("left", 10)).frog.x, a.frog.x - 32, "x after holding left 10 frames: one more hop only");
    await t.bot.wait(1);
    t.bot.eq((await t.bot.press("right", 0)).frog.x, a.frog.x - 16, "x after one right press");
    await t.bot.wait(1);
    await t.bot.press("right", 0);
    const b = await t.probe();
    t.bot.eq([b.frog.row, b.frog.x], [11, a.frog.x], "back at the start");
    await hopUp(t);
    const up = await t.probe();
    t.bot.eq(up.frog.row, 10, "row after one up press");
    const down = await t.bot.press("down", 0);
    t.bot.eq(down.frog.row, 11, "row after one down press");
    for (let i = 0; i < 900; i++) {
      const p = await t.probe();
      if (landsOn(p, 10)) break;
      await t.bot.wait(1);
    }
    const held = await t.bot.hold("up", 20);
    t.bot.eq(held.frog.row, 10, "row after holding up 20 frames: one hop only");
  },

  async R2(t) {
    const a = await t.bot.start();
    t.bot.eq(a.lanes.map((l) => l.row).sort((x, y) => x - y), [2, 3, 4, 5, 7, 8, 9, 10], "river rows");
    for (const l of a.lanes) t.bot.eq(l.logs.length, 4, `logs in lane ${l.row}`);
    for (const [r1, r2] of [[10, 9], [9, 8], [8, 7], [5, 4], [4, 3], [3, 2]]) {
      t.bot.ok(lane(a, r1).dir === -lane(a, r2).dir, `lanes ${r1} and ${r2} should float opposite ways`);
    }
    const b = await t.bot.wait(300);
    for (const l of b.lanes) {
      const l0 = lane(a, l.row);
      t.bot.eq(l.logs.length, 4, `logs in lane ${l.row} later`);
      const want = ((((l0.logs[0].x + 64 + l.dir * l.speed * 300) % 320) + 320) % 320) - 64;
      t.bot.near(l.logs[0].x, want, `log position in lane ${l.row} after 300 frames`, 0.05);
    }
  },

  async R3(t) {
    await t.bot.start();
    await t.poke({ lives: 99 });
    await hopUp(t);
    const a = await t.probe();
    t.bot.eq(a.frog.row, 10, "row after hopping onto a log");
    const l = lane(a, 10);
    const b = await t.bot.wait(20);
    t.bot.eq(b.frog.row, 10, "still on the log");
    t.bot.near(b.frog.x - a.frog.x, l.dir * l.speed * 20, "how far the frog floated in 20 frames", 0.01);
  },

  async R4(t) {
    await t.bot.start();
    const a = await hopIntoWater(t);
    t.bot.eq(a.lives, 2, "lives right after landing in the water");
    t.bot.ok(a.dying > 0, "the frog should be splashing");
    const b = await t.bot.wait(10);
    t.bot.eq([b.lives, b.mode], [2, "play"], "lives and mode 10 frames later");
    const c = await t.bot.wait(20);
    t.bot.eq([c.frog.row, c.frog.x, c.lives], [11, a.startX, 2], "frog back at the start 30 frames after the splash");
  },

  async R5(t) {
    await t.bot.start();
    await hopUp(t);
    const p = await t.bot.reach(() => "", (q) => q.lives < 3, "a life lost by floating off the edge", { every: 10, max: 3000 });
    t.bot.eq(p.lives, 2, "lives after floating off the edge");
    t.bot.eq(p.lastDeath, "edge", "why the life was lost");
    t.bot.ok(p.frog.cx < 0 || p.frog.cx >= p.W, "the frog should be past the screen edge");
  },

  async R6(t) {
    const a = await t.bot.start();
    const b = await t.bot.wait(600);
    t.bot.eq([b.lives, b.frog.row, b.mode], [3, 11, "play"], "after 600 frames on the start row");
    await t.poke({ lives: 99 });
    await climbTo(t, 6);
    const c = await t.probe();
    const d = await t.bot.wait(600);
    t.bot.eq([d.frog.row, d.lives, d.mode], [6, c.lives, "play"], "after 600 frames on the middle row");
    t.bot.ok(a.lives === 3, "start lives");
  },

  async R7(t) {
    await t.bot.start();
    const r = await cross(t);
    const { before, after } = /** @type {any} */ (r);
    t.bot.eq(after.score, 100, "score after reaching the top bank");
    t.bot.eq(after.lives, before.lives, "lives after reaching the top bank");
    t.bot.eq([after.frog.row, after.frog.x, after.crossings], [11, after.startX, 1], "frog back at the start after a crossing");
  },

  async R8(t) {
    await t.bot.start();
    await cross(t);
    const a = await t.probe();
    for (const l of a.lanes) t.bot.near(l.speed, l.base + 0.1, `speed in lane ${l.row} after 1 crossing`, 0.001);
    await t.poke({ crossings: 9 });
    const b = await t.bot.wait(1);
    for (const l of b.lanes) t.bot.near(l.speed, l.base + 0.5, `top speed in lane ${l.row}`, 0.001);
  },

  async R9(t) {
    const a = await t.bot.start();
    t.bot.eq(a.lives, 3, "lives at the start");
    for (const want of [2, 1]) {
      const p = await hopIntoWater(t);
      t.bot.eq([p.lives, p.mode], [want, "play"], "lives after a splash");
      await t.bot.wait(31);
    }
    const last = await hopIntoWater(t);
    t.bot.eq(last.lives, 0, "lives after the third splash");
    const end = await t.bot.wait(60);
    t.bot.eq(end.mode, "over", "mode within 60 frames of the last life");
  },

  async R10(t) {
    await t.bot.start();
    await cross(t);
    await t.poke({ lives: 1 });
    await hopIntoWater(t);
    const end = await t.bot.wait(60);
    t.bot.eq(end.mode, "over", "mode after the last life");
    t.bot.eq(end.score, 100, "score at the end");
    await t.reset({ keepSave: true });
    const p = await t.probe();
    t.bot.eq([p.mode, p.best], ["title", 100], "mode and best after a restart");
  },
};
